"""The desktop window HTML/CSS/JS — bundled as a single string for PyInstaller."""

HTML = r"""
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Anuvadini Defender</title>
<style>
:root{
  --bg:#f7f9fc;--card:#ffffff;--line:#e4eaf0;
  --txt:#0d1b26;--muted:#7a8fa0;
  --accent:#1aaf72;--accent2:#16c97f;
  --orange:#f97316;--pink:#e040a0;--teal:#14b8a6;
  --err:#dc2626;
  --shlg:0 8px 48px rgba(13,27,38,.14);
}
*{box-sizing:border-box;margin:0;padding:0}
html,body{height:100%;overflow:hidden}
body{
  font-family:'Segoe UI',system-ui,sans-serif;
  background:var(--bg);color:var(--txt);
  display:flex;align-items:center;justify-content:center;
  min-height:100vh;
  -webkit-user-select:none;user-select:none;
  background-image:
    radial-gradient(ellipse 800px 500px at 0% 0%,rgba(26,175,114,.07),transparent 60%),
    radial-gradient(ellipse 600px 400px at 100% 100%,rgba(20,184,166,.06),transparent 60%);
}
.win{
  width:100%;max-width:960px;margin:20px;
  background:var(--card);border-radius:20px;
  border:1px solid var(--line);box-shadow:var(--shlg);overflow:hidden;
}
/* ── header ── */
.hdr{
  display:flex;align-items:center;justify-content:space-between;
  padding:14px 28px;border-bottom:1px solid var(--line);
  background:linear-gradient(135deg,#fafcff,#f0f8f5);
}
.hdr-brand{display:flex;align-items:center;gap:0}
.hdr-logo{height:40px;width:auto}
.hdr-sep{width:1px;height:28px;background:var(--line);margin:0 16px}
.hdr-sub{font-size:12px;font-weight:700;color:var(--muted);letter-spacing:.08em;text-transform:uppercase}
.hdr-chip{
  display:none;align-items:center;gap:7px;
  font-size:12px;font-weight:600;
  background:#f0fdf8;border:1px solid #a7f3d0;color:#065f46;
  border-radius:999px;padding:5px 14px;
}
.chip-dot{width:7px;height:7px;border-radius:50%;background:#10b981;
  box-shadow:0 0 0 0 rgba(16,185,129,.45);animation:glow 2s infinite}
@keyframes glow{0%{box-shadow:0 0 0 0 rgba(16,185,129,.4)}70%{box-shadow:0 0 0 8px transparent}100%{box-shadow:0 0 0 0 transparent}}
/* ── body ── */
.body{padding:40px 48px 36px;min-height:460px;display:flex;align-items:center;justify-content:center}
/* boot */
#view-boot{display:flex;flex-direction:column;align-items:center;gap:20px}
.ring{width:54px;height:54px;border:3.5px solid #e4eaf0;border-top-color:var(--accent);border-radius:50%;animation:spin .7s linear infinite}
@keyframes spin{to{transform:rotate(360deg)}}
.boot-lbl{font-size:14px;color:var(--muted);font-weight:500}
/* qr grid */
#view-qr{width:100%;display:grid;grid-template-columns:300px 1fr;gap:60px;align-items:center}
/* QR box */
.qrbox{
  position:relative;width:300px;height:300px;
  background:#fff;border-radius:22px;padding:18px;
  border:1.5px solid var(--line);
  box-shadow:0 12px 40px rgba(26,175,114,.12),0 2px 8px rgba(13,27,38,.06);
}
.qrbox img{width:100%;height:100%;border-radius:10px;image-rendering:pixelated;display:block}
.scanbar{
  position:absolute;left:20px;right:20px;height:2.5px;border-radius:2px;
  background:linear-gradient(90deg,transparent,var(--accent),var(--accent2),transparent);
  box-shadow:0 0 14px 2px rgba(26,175,114,.5);
  animation:scanmove 2.8s ease-in-out infinite;
}
@keyframes scanmove{
  0%  {top:20px;opacity:1}
  40% {top:118px;opacity:.6}
  50% {top:148px;opacity:0}   /* fade through centre logo */
  60% {top:178px;opacity:.6}
  100%{top:265px;opacity:1}
}
.c{position:absolute;width:26px;height:26px;border-color:var(--accent);border-style:solid}
.c.tl{top:8px;left:8px;border-width:3px 0 0 3px;border-radius:5px 0 0 0}
.c.tr{top:8px;right:8px;border-width:3px 3px 0 0;border-radius:0 5px 0 0}
.c.bl{bottom:8px;left:8px;border-width:0 0 3px 3px;border-radius:0 0 0 5px}
.c.br{bottom:8px;right:8px;border-width:0 3px 3px 0;border-radius:0 0 5px 0}
.qr-ov{
  position:absolute;inset:0;border-radius:22px;
  background:rgba(247,249,252,.94);backdrop-filter:blur(6px);
  display:none;flex-direction:column;align-items:center;justify-content:center;gap:12px;
}
.qr-ov.show{display:flex}
.ring-sm{width:30px;height:30px;border:3px solid #e4eaf0;border-top-color:var(--accent);border-radius:50%;animation:spin .7s linear infinite}
.qr-ov p{font-size:13px;font-weight:600;color:var(--muted)}
/* footer under QR */
.qr-foot{display:flex;align-items:center;justify-content:space-between;margin-top:16px}
.dev-tag{display:flex;align-items:center;gap:7px;font-size:12px;color:var(--muted)}
.dev-tag svg{opacity:.4}
/* right info */
.eyebrow{
  font-size:11px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;
  color:var(--accent);margin-bottom:10px;display:flex;align-items:center;gap:8px;
}
.eyebrow::before{content:'';display:block;width:18px;height:2px;background:var(--accent);border-radius:2px}
.info h2{font-size:28px;font-weight:800;color:var(--txt);line-height:1.18;letter-spacing:-.03em}
.info h2 em{
  font-style:normal;
  background:linear-gradient(90deg,var(--orange),var(--pink) 50%,var(--teal));
  -webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;
}
.info-sub{font-size:13.5px;color:var(--muted);line-height:1.65;margin-top:10px;max-width:340px}
/* steps */
.steps{margin-top:26px;display:flex;flex-direction:column;gap:0}
.step{display:flex;align-items:flex-start;gap:14px;padding:11px 0;position:relative}
.step:not(:last-child)::after{
  content:'';position:absolute;left:14px;top:40px;bottom:-6px;width:1.5px;
  background:linear-gradient(to bottom,#c8e6da,transparent);
}
.step-n{
  flex:none;width:28px;height:28px;border-radius:8px;
  background:linear-gradient(135deg,var(--accent),#0d8a55);
  color:#fff;font-weight:800;font-size:13px;
  display:grid;place-items:center;
  box-shadow:0 4px 12px rgba(26,175,114,.28);margin-top:2px;
}
.step-txt b{display:block;font-size:14px;font-weight:700;color:var(--txt)}
.step-txt span{display:block;font-size:12.5px;color:var(--muted);margin-top:2px}
/* waiting */
.status-bar{
  display:inline-flex;align-items:center;gap:9px;margin-top:24px;
  background:#f0fdf8;border:1.5px solid #a7f3d0;color:#065f46;
  font-size:13px;font-weight:600;border-radius:12px;padding:10px 16px;
}
/* done */
#view-done{display:flex;flex-direction:column;align-items:center;text-align:center;gap:20px;padding:20px 0}
.tick{
  width:96px;height:96px;border-radius:50%;
  background:radial-gradient(circle,#dcfce7,#bbf7d0);
  display:grid;place-items:center;
  box-shadow:0 0 0 12px rgba(16,185,129,.08),0 12px 32px rgba(16,185,129,.18);
  animation:popIn .5s cubic-bezier(.22,1.36,.36,1) both;
}
@keyframes popIn{from{transform:scale(.3);opacity:0}to{transform:scale(1);opacity:1}}
.tick svg{width:46px;height:46px;stroke:#16a34a;stroke-width:3;fill:none;stroke-linecap:round;stroke-linejoin:round}
.done-name{font-size:24px;font-weight:800;color:var(--txt);letter-spacing:-.02em}
.done-name small{display:block;font-size:13.5px;color:var(--muted);font-weight:500;margin-top:4px}
.live-pill{
  display:inline-flex;align-items:center;gap:8px;
  background:#f0fdf8;border:1.5px solid #a7f3d0;color:#065f46;
  font-size:13px;font-weight:600;border-radius:999px;padding:9px 20px;
}
.done-msg{font-size:14px;color:var(--muted);max-width:380px;line-height:1.7}
/* buttons */
.btn{
  appearance:none;border:1.5px solid var(--line);background:#fff;color:var(--txt);
  font-size:13px;font-weight:600;padding:9px 20px;border-radius:11px;cursor:pointer;
  box-shadow:0 2px 6px rgba(13,27,38,.06);transition:all .15s;
}
.btn:hover{background:#f3f7fb;border-color:#c8d5e0;box-shadow:0 4px 12px rgba(13,27,38,.1)}
.btn.primary{
  background:linear-gradient(135deg,#1aaf72,#0e9e62);
  border-color:transparent;color:#fff;
  box-shadow:0 4px 16px rgba(26,175,114,.35);
}
.btn.primary:hover{filter:brightness(1.06);box-shadow:0 6px 22px rgba(26,175,114,.45)}
.err{color:var(--err);font-size:12.5px;margin-top:8px;font-weight:500;min-height:16px}
.hidden{display:none!important}
</style>
</head>
<body>
<div class="win">
  <!-- header -->
  <div class="hdr">
    <div class="hdr-brand">
      <img class="hdr-logo" id="hdr-logo" alt="Anuvadini" src="data:image/png;base64,">
      <div class="hdr-sep"></div>
      <span class="hdr-sub">Defender</span>
    </div>
    <div class="hdr-chip" id="hdr-chip">
      <span class="chip-dot"></span> Protected
    </div>
  </div>
  <!-- body -->
  <div class="body">
    <!-- boot -->
    <div id="view-boot">
      <div class="ring"></div>
      <p class="boot-lbl">Starting Anuvadini Defender…</p>
    </div>
    <!-- qr -->
    <div id="view-qr" class="hidden">
      <div>
        <div class="qrbox">
          <img id="qr-img" alt="Pairing QR">
          <div class="scanbar"></div>
          <div class="c tl"></div><div class="c tr"></div>
          <div class="c bl"></div><div class="c br"></div>
          <div class="qr-ov" id="qr-ov">
            <div class="ring-sm"></div>
            <p id="qr-ov-txt">Linking…</p>
          </div>
        </div>
        <div class="qr-foot">
          <div class="dev-tag">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
              <rect x="2" y="3" width="20" height="14" rx="2"/>
              <path d="M8 21h8M12 17v4"/>
            </svg>
            <span id="qr-dev">This PC</span>
          </div>
          <button class="btn" style="padding:7px 14px;font-size:12px" onclick="newCode()">↻ Refresh code</button>
        </div>
      </div>
      <div class="info">
        <div class="eyebrow">Quick Setup</div>
        <h2>Link this PC to <em>your account</em></h2>
        <p class="info-sub">Just like WhatsApp Web — scan once and your PC is linked. No passwords, no USB drives. Done in seconds.</p>
        <ol class="steps">
          <li class="step">
            <div class="step-n">1</div>
            <div class="step-txt">
              <b>Open the Anuvadini attendance app</b>
              <span>on your phone — check in as usual first</span>
            </div>
          </li>
          <li class="step">
            <div class="step-n">2</div>
            <div class="step-txt">
              <b>Tap "Scan Work PC"</b>
              <span>find it on your home dashboard</span>
            </div>
          </li>
          <li class="step">
            <div class="step-n">3</div>
            <div class="step-txt">
              <b>Point your camera at this QR code</b>
              <span>this PC links to your account instantly</span>
            </div>
          </li>
        </ol>
        <div class="status-bar" id="qr-status">
          <span class="chip-dot"></span>
          Waiting for scan…
        </div>
        <div class="err" id="qr-err"></div>
      </div>
    </div>
    <!-- done -->
    <div id="view-done" class="hidden">
      <div class="tick">
        <svg viewBox="0 0 24 24"><path d="M5 13l4 4L19 7"/></svg>
      </div>
      <div class="done-name" id="done-name">Linked</div>
      <div class="live-pill"><span class="chip-dot"></span> Monitoring active</div>
      <p class="done-msg">This PC is linked to your account and fully protected. Anuvadini Defender runs silently in the background.</p>
      <button class="btn primary" onclick="minimizeApp()">Minimise to background</button>
    </div>
  </div>
</div>
<script>
const $=id=>document.getElementById(id);
let state={host:'',pairId:null,pollMs:2000,timer:null};
function showView(v){['boot','qr','done'].forEach(n=>$('view-'+n).classList.toggle('hidden',n!==v));}
async function api(name,...args){return window.pywebview.api[name](...args);}
let booted=false;
function tryBoot(){if(window.pywebview&&!booted){booted=true;boot();}}
window.addEventListener('pywebviewready',tryBoot);
setTimeout(tryBoot,400);
async function boot(){
  const s=await api('boot');
  state.host=s.serverHost||'';
  if(s.hostname)$('qr-dev').textContent=s.hostname;
  if(s.paired&&s.employee){showDone(s.employee,true);return;}
  startPairing();
}
async function startPairing(){
  showView('qr');$('qr-err').textContent='';$('qr-ov').classList.remove('show');
  const r=await api('create_session');
  if(r.error){$('qr-err').textContent=r.error;return;}
  state.pairId=r.pairId;state.pollMs=r.pollMs||2000;
  $('qr-img').src=r.qrImage;
  if(r.deviceName||r.hostname)$('qr-dev').textContent=[r.deviceName,r.hostname].filter(Boolean).join(' · ');
  clearInterval(state.timer);
  state.timer=setInterval(checkStatus,state.pollMs);
}
function newCode(){clearInterval(state.timer);startPairing();}
async function checkStatus(){
  if(!state.pairId)return;
  const r=await api('poll',state.pairId);
  if(r.status==='paired'){
    clearInterval(state.timer);
    $('qr-ov-txt').textContent='Linking…';$('qr-ov').classList.add('show');
    const f=await api('finish',state.pairId);
    if(f.ok){showDone(f.employee,false);}
    else{$('qr-ov').classList.remove('show');$('qr-err').textContent=f.error||'Could not finish linking.';}
  }else if(r.status==='expired'){
    clearInterval(state.timer);
    $('qr-status').innerHTML='<span style="color:var(--muted)">Code expired — tap Refresh.</span>';
  }else if(r.status==='offline'){
    $('qr-err').textContent='Cannot reach server. Check network.';
  }else{$('qr-err').textContent='';}
}
function showDone(emp,already){
  showView('done');
  $('done-name').innerHTML=(emp.name||'Linked')+'<small>'+[emp.department,emp.uid].filter(Boolean).join(' · ')+'</small>';
  $('hdr-chip').style.display='inline-flex';
}
function minimizeApp(){api('minimize');}
</script>
</body>
</html>
"""
